export class Sprite {
  constructor(name) {
    this.name = name;
    this.children = [];
    this.parent = null;
  }

  add(child) {
    child.parent = this;
    this.children.push(child);
    return child;
  }

  path() {
    return this.parent ? `${this.parent.path()}/${this.name}` : this.name;
  }
}

